sys_ux_client_script.script:
async function handler({ api, event, helpers, imports }) { 
    // Validate and log the helpers.snHttp object
    console.log("snHttp object:", helpers.snHttp);

    if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
        console.error("Error: helpers.snHttp is not properly initialized or is not callable.");
        return;
    }
    var selectedProperty = api.state.selectedProperty

    var properties = api.data.sam_properties_1.output.properties; // Retrieve the properties

    console.log("Properties selected ", selectedProperty);
    console.log("Properties to update:", properties);
    properties = properties.filter((item) => selectedProperty.property.includes(item.property));
    console.log("properties final",properties);

    for (const property of properties) {
        const requestData = {
            sysparm_property: property.property, // Property name
            sysparm_suggested_value: property.suggested_value // Suggested value
        };

        console.log("Request payload being sent:", JSON.stringify(requestData, null, 2));

        try {
            // Use snHttp to send the API request
            const response = await helpers.snHttp(
                "/api/985627/property_update", // API endpoint
                {
                    method: "POST", // HTTP method
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify(requestData) // Pass the request payload
                }
            );

            // Log the response for verification
            console.log("Response status:", response.status);
            console.log("Response body:", response);

            // Process the API response
            if (response.status === 200 || response.response.result.status == "success") {
                console.log(`Property ${property.property} updated successfully in the table.`);

                api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                    items: [
                        {
                            id: 'alert2',
                            status: 'positive',
                            icon: 'info-circle-outline',
                            content: await helpers.translate('Property updated successfully'),
                            action: { type: 'dismiss' }
                        }
                    ]
                });
            } else {
                console.error(`Failed to updated Property`, response);

                api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                    items: [
                        {
                            id: 'alert2',
                            status: 'critical',
                            icon: 'info-circle-outline',
                            content: await helpers.translate('Failed to updated Property'),
                            action: { type: 'dismiss' }
                        }
                    ]
                });
            }
        } catch (error) {
            // Handle any errors in the API call
            console.error(`Error updating property ${property.property}:`, error);
            if (error.response) {
                console.error("Error response:", error.response);
            } else if (error.data) {
                console.error("Error data:", error.data);
            }
        }
    }
}
